package com.witchersbestiary.signs;
import java.util.*;import net.minecraft.network.*;import net.minecraft.network.codec.PacketCodec;import net.minecraft.network.packet.CustomPayload;import net.minecraft.util.Identifier;import net.fabricmc.fabric.api.networking.v1.*;
public final class SignPackets {
 public record Intent(UUID session,long sequence,int action,int sign) implements CustomPayload {public static final Id<Intent>ID=new Id<>(Identifier.of("witchersbestiary:sign_intent"));public static final PacketCodec<RegistryByteBuf,Intent> CODEC=PacketCodec.of((p,b)->{b.writeUuid(p.session);b.writeLong(p.sequence);b.writeVarInt(p.action);b.writeVarInt(p.sign);},b->new Intent(b.readUuid(),b.readLong(),b.readVarInt(),b.readVarInt()));public Id<Intent>getId(){return ID;}}
 public record View(UUID session,int learned,int selected,float energy,int cooldown,float shield,int shieldTicks,int trapTicks) implements CustomPayload {public static final Id<View>ID=new Id<>(Identifier.of("witchersbestiary:sign_view"));public static final PacketCodec<RegistryByteBuf,View> CODEC=PacketCodec.of((p,b)->{b.writeUuid(p.session);b.writeVarInt(p.learned);b.writeVarInt(p.selected);b.writeFloat(p.energy);b.writeVarInt(p.cooldown);b.writeFloat(p.shield);b.writeVarInt(p.shieldTicks);b.writeVarInt(p.trapTicks);},b->new View(b.readUuid(),b.readVarInt(),b.readVarInt(),b.readFloat(),b.readVarInt(),b.readFloat(),b.readVarInt(),b.readVarInt()));public Id<View>getId(){return ID;}}
 public static void initialize(){PayloadTypeRegistry.playC2S().register(Intent.ID,Intent.CODEC);PayloadTypeRegistry.playS2C().register(View.ID,View.CODEC);ServerPlayNetworking.registerGlobalReceiver(Intent.ID,(p,c)->c.server().execute(()->SignManager.intent(c.player(),p)));}
}
